def count_good_half_sum_rotations(nums):
    n=len(nums);half=n//2;left=sum(nums[:half]);right=sum(nums[half:]);answer=left>right
    for i in range(n-1):
        left-=nums[i];right+=nums[i];left+=nums[(i+half)%n];right-=nums[(i+half)%n];answer+=left>right
    return answer

